cat > src/board.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { BoardError, createBoard, type BoardErrorCode, type ColumnConfig } from "./board";

test("board errors carry a code", () => {
  const error = new BoardError("WIP_LIMIT", "Column Review is full");
  expect(error).toBeInstanceOf(Error);
  expect(error.code).toBe("WIP_LIMIT");
});

const defaultColumns: ColumnConfig[] = [
  { name: "Backlog" },
  { name: "Doing" },
  { name: "Review" },
  { name: "Done" },
];

function setup(columns: ColumnConfig[] = defaultColumns) {
  const clock = { t: 1_000 };
  const board = createBoard({ columns, now: () => clock.t });
  return { board, clock };
}

function expectBoardError(fn: () => unknown, code: BoardErrorCode) {
  let caught: unknown;
  try {
    fn();
  } catch (e) {
    caught = e;
  }
  expect(caught).toBeInstanceOf(BoardError);
  expect((caught as BoardError).code).toBe(code);
}

describe("adding", () => {
  test("addCard returns sequential ids and appends to the first column", () => {
    const { board } = setup();
    expect(board.addCard("first")).toBe("C1");
    expect(board.addCard("second")).toBe("C2");
    expect(board.cardsIn("Backlog")).toEqual(["C1", "C2"]);
    expect(board.cardsIn("Doing")).toEqual([]);
  });
});
EOF
bun test 2>&1 | tail -5

